function buildLeanModeScript(settings) {
  const config = {
    leanMode: settings?.leanMode === true,
    reduceMotion: settings?.reduceMotion === true,
    hideProfileDecorations: settings?.hideProfileDecorations === true,
    staticAnimatedAvatars: settings?.staticAnimatedAvatars === true,
    textOnlyMode: settings?.textOnlyMode === true
  };

  const body = [
    '"use strict";',
    'const root = document.documentElement;',
    'if (!root) return;',
    'const styleId = "sweetcord-lean-mode-style";',
    'let style = document.getElementById(styleId);',
    'if (!style) { style = document.createElement("style"); style.id = styleId; (document.head || root).appendChild(style); }',
    'if (style.textContent !== css) style.textContent = css;',
    'root.classList.toggle("sweetcord-lean-mode", cfg.leanMode);',
    'root.classList.toggle("sweetcord-reduced-motion", cfg.reduceMotion);',
    'root.classList.toggle("sweetcord-trim-profile-decorations", cfg.hideProfileDecorations);',
    'root.classList.toggle("sweetcord-text-only-mode", cfg.textOnlyMode);',
    'root.classList.add("sweetcord-voice-only-mode");',
    'if (cfg.textOnlyMode) { if (window.__sweetCordAvatarObserver) { window.__sweetCordAvatarObserver.disconnect(); window.__sweetCordAvatarObserver = null; window.__sweetCordAvatarObserverInstalled = false; } return; }',
    'const previousStaticState = window.__sweetCordStaticAvatarState;',
    'window.__sweetCordStaticAvatarState = cfg.staticAnimatedAvatars;',
    'const avatarSelector = \'img[src*="/avatars/"], img[data-sweetcord-original-src]\';',
    'const clearSavedAvatar = (img) => { img.removeAttribute("data-sweetcord-original-src"); img.removeAttribute("data-sweetcord-original-srcset"); img.removeAttribute("data-sweetcord-static-src"); };',
    'const normalizeAvatar = (img) => {',
    '  if (!(img instanceof HTMLImageElement)) return;',
    '  const source = img.getAttribute("src") || "";',
    '  const savedSource = img.getAttribute("data-sweetcord-original-src");',
    '  const staticSource = img.getAttribute("data-sweetcord-static-src");',
    '  const failedSource = img.getAttribute("data-sweetcord-static-failed-src");',
    '  if (failedSource && failedSource !== source) img.removeAttribute("data-sweetcord-static-failed-src");',
    '  else if (cfg.staticAnimatedAvatars && failedSource === source) return;',
    '  const pathOnly = source.split(/[?#]/, 1)[0].toLowerCase();',
    '  const finalSegment = pathOnly.slice(pathOnly.lastIndexOf("/") + 1);',
    '  const isAnimatedAvatar = pathOnly.includes("/avatars/") && finalSegment.startsWith("a_") && finalSegment.endsWith(".gif");',
    '  if (!cfg.staticAnimatedAvatars) {',
    '    if (savedSource && staticSource && source === staticSource) {',
    '      img.setAttribute("src", savedSource);',
    '      const originalSet = img.getAttribute("data-sweetcord-original-srcset") || "";',
    '      if (originalSet) img.setAttribute("srcset", originalSet); else img.removeAttribute("srcset");',
    '    }',
    '    clearSavedAvatar(img); img.removeAttribute("data-sweetcord-static-failed-src");',
    '    return;',
    '  }',
    '  if (isAnimatedAvatar) {',
    '    if (!savedSource || savedSource !== source) {',
    '      img.setAttribute("data-sweetcord-original-src", source);',
    '      img.setAttribute("data-sweetcord-original-srcset", img.getAttribute("srcset") || "");',
    '    }',
    '    const queryStart = source.search(/[?#]/);',
    '    const base = queryStart < 0 ? source : source.slice(0, queryStart);',
    '    const suffix = queryStart < 0 ? "" : source.slice(queryStart);',
    '    const stillSource = base.slice(0, -4) + ".png" + suffix;',
    '    img.setAttribute("data-sweetcord-static-src", stillSource);',
    '    img.removeAttribute("srcset");',
    '    if (source !== stillSource) {',
    '      img.addEventListener("error", () => {',
    '        if (img.getAttribute("src") !== stillSource) return;',
    '        const original = img.getAttribute("data-sweetcord-original-src");',
    '        const originalSet = img.getAttribute("data-sweetcord-original-srcset") || "";',
    '        if (original) { img.setAttribute("data-sweetcord-static-failed-src", original); img.setAttribute("src", original); }',
    '        if (originalSet) img.setAttribute("srcset", originalSet); else img.removeAttribute("srcset");',
    '        clearSavedAvatar(img);',
    '      }, { once: true });',
    '      img.setAttribute("src", stillSource);',
    '    }',
    '  } else if (savedSource && staticSource && source !== staticSource) {',
    '    // Discord reused the element for a different non-animated asset; never restore stale URLs.',
    '    clearSavedAvatar(img);',
    '  }',
    '};',
    'const processTree = (node) => {',
    '  if (!(node instanceof Element)) return;',
    '  if (node.matches(avatarSelector)) normalizeAvatar(node);',
    '  if (node.querySelectorAll) node.querySelectorAll(avatarSelector).forEach(normalizeAvatar);',
    '};',
    'const getAvatarRoot = () => document.getElementById("app-mount") || document;',
    'const processExistingAvatars = () => getAvatarRoot().querySelectorAll(avatarSelector).forEach(normalizeAvatar);',
    'if (!window.__sweetCordAvatarObserverInstalled) {',
    '  const pendingNodes = new Set();',
    '  const pendingImages = new Set();',
    '  let frameQueued = false;',
    '  const flushPending = () => {',
    '    frameQueued = false;',
    '    const queuedNodes = Array.from(pendingNodes);',
    '    const isCoveredByQueuedNode = (image) => { let current = image; while (current) { if (pendingNodes.has(current)) return true; current = current.parentElement; } return false; }',
    '    for (const image of pendingImages) if (!isCoveredByQueuedNode(image)) normalizeAvatar(image);',
    '    for (const node of queuedNodes) {',
    '      let parent = node.parentElement;',
    '      let coveredByQueuedAncestor = false;',
    '      while (parent) { if (pendingNodes.has(parent)) { coveredByQueuedAncestor = true; break; } parent = parent.parentElement; }',
    '      if (!coveredByQueuedAncestor) processTree(node);',
    '    }',
    '    pendingImages.clear();',
    '    pendingNodes.clear();',
    '  };',
    '  const queueFlush = () => { if (!frameQueued) { frameQueued = true; window.requestAnimationFrame(flushPending); } };',
    '  const observer = new MutationObserver((records) => {',
    '    for (const record of records) {',
    '      if (record.type === "attributes") {',
    '        if (record.target instanceof HTMLImageElement && record.target.matches(avatarSelector)) pendingImages.add(record.target);',
    '      } else {',
    '        for (const node of record.addedNodes) if (node instanceof Element) pendingNodes.add(node);',
    '      }',
    '    }',
    '    if (pendingNodes.size || pendingImages.size) queueFlush();',
    '  });',
    '  observer.observe(getAvatarRoot(), { childList: true, subtree: true, attributes: true, attributeFilter: ["src"] });',
    '  window.__sweetCordAvatarObserver = observer;',
    '  window.__sweetCordAvatarObserverInstalled = true;',
    '}',
    'if (previousStaticState !== cfg.staticAnimatedAvatars || !window.__sweetCordAvatarInitialScanDone) {',
    '  processExistingAvatars();',
    '  window.__sweetCordAvatarInitialScanDone = true;',
    '}',
  ];
  body.splice(12, 0, "const chromeRoot = document.getElementById(\"app-mount\");\nconst chromeRoutePrefixes = [\"/store\", \"/shop\", \"/quests\", \"/quest-home\", \"/nitro\", \"/discovery\", \"/guild-discovery\", \"/activities\"];\nconst isChromePromoRoute = (rawHref) => {\n  try {\n    const url = new URL(rawHref, location.origin);\n    if (url.origin !== location.origin) return false;\n    const path = url.pathname.replace(/\\/+$/, \"\").toLowerCase() || \"/\";\n    return chromeRoutePrefixes.some((route) => path === route || path.startsWith(route + \"/\"));\n  } catch { return false; }\n};\nconst isChromeNavigationItem = (element) => {\n  let node = element;\n  for (let depth = 0; node && depth < 7 && node !== chromeRoot; depth += 1, node = node.parentElement) {\n    if (node.matches(\"nav, [role='navigation']\")) return true;\n    const name = typeof node.className === \"string\" ? node.className : \"\";\n    if (/(sidebar|guildsbar|navigation|navitem|nav-item|listitem)/i.test(name)) return true;\n  }\n  return false;\n};\nconst chromeHideTarget = (element) => {\n  let node = element;\n  for (let depth = 0; node && depth < 5 && node !== chromeRoot; depth += 1, node = node.parentElement) {\n    const name = typeof node.className === \"string\" ? node.className : \"\";\n    if (node.matches(\"li, [role='listitem'], [data-list-item-id]\") || /(navitem|nav-item|sidebaritem|sidebar-item|listitem|list-item)/i.test(name)) return node;\n  }\n  return element;\n};\nconst shouldHideChromeElement = (element) => {\n  if (!(element instanceof Element) || !chromeRoot || !chromeRoot.contains(element)) return false;\n  const className = typeof element.className === \"string\" ? element.className : \"\";\n  if (/(nitroUpsell|premiumPromo|questHome|questCard|shopUpsell|nitroBanner|questPromo|shopPromo)/i.test(className)) return true;\n  if (element.matches(\"a[href]\") && isChromePromoRoute(element.getAttribute(\"href\") || \"\")) return true;\n  if (!element.matches(\"a, button, [role='button'], [role='link']\") || !isChromeNavigationItem(element)) return false;\n  const label = [element.getAttribute(\"aria-label\"), element.getAttribute(\"title\"), element.innerText, element.textContent]\n    .filter(Boolean).join(\" \").replace(/\\s+/g, \" \").trim().toLowerCase();\n  return /^(nitro|shop|store|quests?|quest home|discovery|guild discovery|activities)(?:\\s|$)/.test(label);\n};\nconst pruneChromeElement = (element) => {\n  if (!shouldHideChromeElement(element)) return;\n  const target = chromeHideTarget(element);\n  if (target && target !== chromeRoot) target.setAttribute(\"data-sweetcord-hidden\", \"true\");\n};\nconst pruneChromeSubtree = (node) => {\n  if (!(node instanceof Element) || !chromeRoot) return;\n  pruneChromeElement(node);\n  if (node.querySelectorAll) {\n    node.querySelectorAll(\"a[href], button, [role='button'], [role='link'], [class*='nitroUpsell' i], [class*='premiumPromo' i], [class*='questHome' i], [class*='questCard' i], [class*='shopUpsell' i]\")\n      .forEach(pruneChromeElement);\n  }\n};\nif (chromeRoot) {\n  if (!window.__sweetCordChromePruneObserverInstalled) {\n    const pendingChromeNodes = new Set();\n    let chromeFrameQueued = false;\n    const flushChromeNodes = () => {\n      chromeFrameQueued = false;\n      const nodes = Array.from(pendingChromeNodes);\n      pendingChromeNodes.clear();\n      for (const node of nodes) pruneChromeSubtree(node);\n    };\n    const queueChromeFlush = () => {\n      if (!chromeFrameQueued) {\n        chromeFrameQueued = true;\n        window.requestAnimationFrame(flushChromeNodes);\n      }\n    };\n    const chromeObserver = new MutationObserver((records) => {\n      for (const record of records) {\n        if (record.type === \"attributes\") {\n          if (record.target instanceof Element) pendingChromeNodes.add(record.target);\n        } else {\n          for (const node of record.addedNodes) if (node instanceof Element) pendingChromeNodes.add(node);\n        }\n      }\n      if (pendingChromeNodes.size) queueChromeFlush();\n    });\n    chromeObserver.observe(chromeRoot, {\n      childList: true,\n      subtree: true,\n      attributes: true,\n      attributeFilter: [\"href\", \"aria-label\", \"title\", \"class\"]\n    });\n    window.__sweetCordChromePruneObserver = chromeObserver;\n    window.__sweetCordChromePruneObserverInstalled = true;\n  }\n  pruneChromeSubtree(chromeRoot);\n}");
  const generatedBody = body.join("\n");

  return "(function(){\nconst cfg = " + JSON.stringify(config) + ";\nconst css = " + JSON.stringify(LEAN_STYLES) + ";\n" + generatedBody + "\n})();";
}

module.exports = { buildLeanModeScript };
